      const data = await res.json();
      if (!data.success) throw new Error(data.error || "API error");

      const stats = { bayut: data.breakdown?.bayut || 0, pf: data.breakdown?.propertyfinder || 0, dld: data.breakdown?.dubaiPulse || 0 };
