      await setDoc(doc(db, "users", v.uid), { verified: true, verifiedLevel: v.level || "basic", verifiedAt: new Date().toISOString(), kycLevel: v.level || "basic" }, { merge: true });
      await logAudit(db, { action: "kyc_approved", userId: v.uid, details: `Level: ${v.level || "basic"}` });
      // Send approval email
